// Validate each application row. Rows missing required fields are marked invalid.
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const name = (r.Name ?? r.name ?? '').toString().trim();
  const email = (r.Email ?? r.email ?? '').toString().trim();
  const errors = [];
  if (!name) errors.push('Missing name');
  const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  if (!emailOk) errors.push('Missing or invalid email');

  out.push({
    json: {
      ...r,
      _name: name,
      _email: email,
      _valid: errors.length === 0,
      _validationErrors: errors.join('; '),
    },
  });
}
return out;

// Apply eligibility rules to valid rows. Normalizes free-text fields before comparing.
// Eligibility: valid data AND score >= 50 AND experience >= 1 year.
const MIN_SCORE = 50;
const MIN_EXPERIENCE_YEARS = 1;

function parseNumber(v) {
  if (v === null || v === undefined) return NaN;
  const cleaned = v.toString().replace(/[^0-9.\-]/g, '');
  return cleaned === '' ? NaN : parseFloat(cleaned);
}
function parseYears(v) {
  if (v === null || v === undefined) return NaN;
  const s = v.toString().toLowerCase();
  const m = s.match(/([0-9]+(?:\.[0-9]+)?)/);
  return m ? parseFloat(m[1]) : NaN;
}

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  let eligible = false;
  let reason = '';

  if (!r._valid) {
    reason = 'Invalid data: ' + (r._validationErrors || 'unknown');
  } else {
    const score = parseNumber(r.Score ?? r.score);
    const years = parseYears(r.Experience ?? r.experience);
    const scoreOk = !isNaN(score) && score >= MIN_SCORE;
    const expOk = !isNaN(years) && years >= MIN_EXPERIENCE_YEARS;
    eligible = scoreOk && expOk;
    if (eligible) {
      reason = 'Meets score and experience thresholds';
    } else {
      const fails = [];
      if (!scoreOk) fails.push('score < ' + MIN_SCORE);
      if (!expOk) fails.push('experience < ' + MIN_EXPERIENCE_YEARS + ' year(s)');
      reason = 'Does not meet: ' + fails.join(', ');
    }
    r._score = isNaN(score) ? null : score;
    r._years = isNaN(years) ? null : years;
  }

  out.push({ json: { ...r, _eligible: eligible, _eligibilityReason: reason } });
}
return out;

// Assign a category and outcome to each candidate.
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  let category;

  if (!r._valid) {
    category = 'Invalid';
  } else if (!r._eligible) {
    category = 'Rejected';
  } else {
    const score = r._score ?? 0;
    if (score >= 80) category = 'Shortlisted';
    else if (score >= 65) category = 'Interview';
    else category = 'Waitlisted';
  }

  out.push({
    json: {
      ...r,
      Status: r._valid ? (r._eligible ? 'Eligible' : 'Not Eligible') : 'Invalid',
      Category: category,
    },
  });
}
return out;
